-- 4) 可选：sys_user 通知偏好列（若你用到了通知功能，顺便补上；幂等跳过）
SET @has_nr = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'sys_user' AND COLUMN_NAME = 'notify_review');
SET @has_nq = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'sys_user' AND COLUMN_NAME = 'notify_quota');
SET @sql_nr = IF(@has_nr = 0, 'ALTER TABLE `sys_user` ADD COLUMN `notify_review` TINYINT NOT NULL DEFAULT 1 COMMENT \'是否开启今日复习提醒通知（1=开 0=关）\'', 'SELECT 1');
SET @sql_nq = IF(@has_nq = 0, 'ALTER TABLE `sys_user` ADD COLUMN `notify_quota`  TINYINT NOT NULL DEFAULT 1 COMMENT \'是否开启AI额度提醒通知（1=开 0=关）\'', 'SELECT 1');
PREPARE stmt FROM @sql_nr; EXECUTE stmt; DEALLOCATE PREPARE stmt;
PREPARE stmt FROM @sql_nq; EXECUTE stmt; DEALLOCATE PREPARE stmt;

